// Basic type deduction
auto x = 5;              // int
auto y = 3.14;           // double
auto z = 'a';            // char
auto str = string("Hi"); // std::string

// Iterator simplification
std::map<int, std::string> myMap;
// Without auto:
std::map<int, std::string>::iterator it = myMap.begin();
// With auto:
auto it = myMap.begin();  // Much cleaner!

// Function return type deduction (C++14)
auto add(int a, int b) {
    return a + b;  // Deduced as int
}

// Lambda types (impossible to write manually)
auto lambda = [](int x) { return x * 2; };

